d #b9ccbd;padding:2mm}td{border-bottom:1px solid #dae3d9;padding:2mm;vertical-align:top}.section{margin-top:5mm}.schedule td:first-child{width:26mm;white-space:nowrap;font-size:8pt;font-weight:bold;color:#117465}.schedule td{padding:1.3mm 2mm}.say{font-size:10.6pt;line-height:1.43}.say p{margin-bottom:2mm}.lesson h2{font-size:19pt}.lesson .prep{font-size:8.5pt;color:#516959;margin-bottom:2mm}.lesson .tag{font-size:8.8pt;margin-bottom:2mm;color:#117465;font-weight:bold}.lesson h3{margin:2.2mm 0 1.4mm;font-size:10.6pt}.lesson .actions{font-size:10pt;line-height:1.4}.lesson .actions li{margin-bottom:1.5mm}.lesson .qa{font-size:9.7pt;padding:3mm;background:#eaf2eb;margin:2mm 0}.lesson .qa p{margin:0 0 1.2mm}.lesson .qa p:last-child{margin:0}.lesson .avoid{font-size:8.6pt;margin-top:2mm}.rule{border:0;border-top:1px solid #ced9cc;margin:4mm 0}.ref{font-size:8.5pt;line-height:1.35}.ref li{margin-bottom:2.5mm}a{color:#11654c;overflow-wrap:anywhere}.blank{padding:3mm 0;border-bottom:1px solid #cad8c8;min-height:12mm}.heuristic{padding:3mm 0;border-bottom:1px solid #d2ddce}.heuristic h3{margin-top:0}.heuristic p{font-size:9.6pt}.heuristic:last-child{border:0}pre{font:8.8pt/1.4 monospace;white-space:pre-wrap;background:#edf3ec;padding:4mm}.line{height:8mm;border-bottom:1px solid #d2ddce}@media print{html{background:white}.page{margin:0}}@media screen and (max-width:820px){.page{width:100%;height:auto;padding:22px;margin:0 0 20px}.foot{position:static;margin-top:25px}.grid{grid-template-columns:1fr}.metrics{flex-wrap:wrap}.metrics div{min-width:50%}.schedule{font-size:9pt}}
